"use client"

import * as React from "react"

import { AppShell } from "@/components/shell/app-shell"
import { GlobalTurnDetection } from "@/components/mockups/eou-timing/global-turn-detection"
import { PersonaTurnTiming } from "@/components/mockups/eou-timing/persona-turn-timing"
import type { WaitWindowValue } from "@/components/mockups/eou-timing/wait-window"
import { MockupShell } from "@/components/shell/mockup-shell"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"
import { PERSONA, SAVED_GLOBAL } from "@/lib/mockups/eou-timing-data"

type Home = "global" | "persona"

export default function EouTimingPage() {
  const [home, setHome] = React.useState<Home>("global")

  const [globalWindow, setGlobalWindow] = React.useState<WaitWindowValue>({
    maxWaitSeconds: SAVED_GLOBAL.maxWaitSeconds,
    minWaitSeconds: SAVED_GLOBAL.minWaitSeconds,
  })

  const onGlobal = home === "global"

  return (
    <MockupShell
      title="Design EOU configuration updates independent from backchanneling"
      actions={
        <ToggleGroup
          onValueChange={(next) => {
            if (next) setHome(next as Home)
          }}
          size="sm"
          type="single"
          value={home}
          variant="outline"
        >
          <ToggleGroupItem value="global">Global Settings</ToggleGroupItem>
          <ToggleGroupItem value="persona">
            Persona · {PERSONA.name}
          </ToggleGroupItem>
        </ToggleGroup>
      }
    >
      <AppShell
        active={onGlobal ? "Global Settings" : "Personas"}
        breadcrumb={onGlobal ? "Global Settings" : `Personas · ${PERSONA.name}`}
        onNavigate={(title) => {
          if (title === "Global Settings") setHome("global")
          if (title === "Personas") setHome("persona")
        }}
      >
        <div className="flex flex-1 flex-col p-3 lg:p-4">
          <div className="mx-auto flex w-full max-w-3xl flex-col gap-6">
            <h1 className="text-2xl font-semibold">
              {onGlobal ? "Global settings" : `Edit persona · ${PERSONA.name}`}
            </h1>
            {onGlobal ? (
              <GlobalTurnDetection
                onWindowChange={setGlobalWindow}
                window={globalWindow}
              />
            ) : (
              <PersonaTurnTiming globalWindow={globalWindow} />
            )}
          </div>
        </div>
      </AppShell>
    </MockupShell>
  )
}

import { Alert02Icon, InformationCircleIcon } from "@hugeicons/core-free-icons"

import { icon } from "@/components/shared/icon"

export const OutOfBandIcon = icon(Alert02Icon, "OutOfBandIcon")

export const ScopeNoteIcon = icon(InformationCircleIcon, "ScopeNoteIcon")

export const FieldHelpIcon = icon(InformationCircleIcon, "FieldHelpIcon")

"use client"

import * as React from "react"

import { Alert, AlertDescription } from "@/components/ui/alert"
import {
  Card,
  CardAction,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { Label } from "@/components/ui/label"
import { Switch } from "@/components/ui/switch"
import {
  DETECTION_MODELS,
  PERSONA,
  SAVED_GLOBAL,
} from "@/lib/mockups/eou-timing-data"

import { ScopeNoteIcon } from "./icons"
import { WaitWindow, type WaitWindowValue } from "./wait-window"

export function PersonaTurnTiming({
  globalWindow,
}: {
  globalWindow: WaitWindowValue
}) {
  const [override, setOverride] = React.useState<null | WaitWindowValue>(
    PERSONA.override,
  )
  const overridden = override !== null
  const active = override ?? globalWindow
  const model = DETECTION_MODELS.find(
    (entry) => entry.id === SAVED_GLOBAL.detectionModelId,
  )

  return (
    <Card>
      <CardHeader>
        <CardTitle>Turn Timing</CardTitle>
        <CardDescription>
          {overridden
            ? `${PERSONA.name} waits on its own values. Global changes no longer reach it.`
            : `${PERSONA.name} waits on the global values. Change them globally and this persona follows.`}
        </CardDescription>
        <CardAction>
          <div className="flex items-center gap-2">
            <Label htmlFor="persona-override">Override global</Label>
            <Switch
              checked={overridden}
              id="persona-override"
              onCheckedChange={(next) =>
                setOverride(next ? { ...globalWindow } : null)
              }
            />
          </div>
        </CardAction>
      </CardHeader>

      <CardContent className="flex flex-col gap-3">
        <WaitWindow
          disabled={!overridden}
          idPrefix="persona"
          onChange={setOverride}
          value={active}
        />
        <Alert>
          <ScopeNoteIcon />
          <AlertDescription>
            Detection model: {model?.label} (set globally). Changes apply to new
            calls only.
          </AlertDescription>
        </Alert>
      </CardContent>
    </Card>
  )
}

"use client"

import * as React from "react"
import { AnimatePresence, motion, useReducedMotion } from "motion/react"

import { Alert, AlertDescription } from "@/components/ui/alert"
import { Field, FieldLabel } from "@/components/ui/field"
import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
} from "@/components/ui/input-group"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import {
  MAX_WAIT_CEILING_SECONDS,
  RECOMMENDED_MAX_WAIT_CEILING_SECONDS,
  RECOMMENDED_MAX_WAIT_FLOOR_SECONDS,
  formatSeconds,
} from "@/lib/mockups/eou-timing-data"

import { FieldHelpIcon, OutOfBandIcon } from "./icons"

export type WaitWindowValue = {
  maxWaitSeconds: number
  minWaitSeconds: number
}

export function WaitWindow({
  disabled = false,
  idPrefix,
  onChange,
  value,
}: {
  disabled?: boolean
  idPrefix: string
  onChange: (value: WaitWindowValue) => void
  value: WaitWindowValue
}) {
  const { maxWaitSeconds, minWaitSeconds } = value
  const belowFloor = maxWaitSeconds < RECOMMENDED_MAX_WAIT_FLOOR_SECONDS
  const aboveCeiling = maxWaitSeconds > RECOMMENDED_MAX_WAIT_CEILING_SECONDS

  const handleNumber =
    (field: keyof WaitWindowValue) =>
    (event: React.ChangeEvent<HTMLInputElement>) => {
      const next = Number(event.target.value)
      if (Number.isNaN(next)) return
      onChange({
        ...value,
        [field]: Math.min(Math.max(next, 0), MAX_WAIT_CEILING_SECONDS),
      })
    }

  return (
    <div className="flex flex-col gap-4">
      <div className="grid gap-4 md:grid-cols-2">
        <WaitField
          disabled={disabled}
          help="How long the agent waits after the caller seems finished. Lower feels snappier."
          id={`${idPrefix}-min-wait`}
          label="Minimum wait (seconds)"
          name="minimum wait"
          onChange={handleNumber("minWaitSeconds")}
          value={minWaitSeconds}
        />

        <WaitField
          disabled={disabled}
          help="The longest the agent waits when it isn't sure. Lower risks interrupting mid-sentence."
          id={`${idPrefix}-max-wait`}
          label="Maximum wait (seconds)"
          name="maximum wait"
          onChange={handleNumber("maxWaitSeconds")}
          value={maxWaitSeconds}
        />
      </div>

      <BandWarning
        aboveCeiling={aboveCeiling && !disabled}
        belowFloor={belowFloor && !disabled}
      />
    </div>
  )
}

function WaitField({
  disabled,
  help,
  id,
  label,
  name,
  onChange,
  value,
}: {
  disabled: boolean
  help: string
  id: string
  label: string
  /** Spoken name for the help button; the visible label's "(seconds)" is noise when read aloud. */
  name: string
  onChange: (event: React.ChangeEvent<HTMLInputElement>) => void
  value: number
}) {
  return (
    <Field>
      <FieldLabel htmlFor={id}>{label}</FieldLabel>
      <InputGroup>
        <InputGroupInput
          disabled={disabled}
          id={id}
          max={MAX_WAIT_CEILING_SECONDS}
          min={0}
          onChange={onChange}
          step={0.1}
          type="number"
          value={value}
        />
        <InputGroupAddon align="inline-end">
          <Tooltip>
            <TooltipTrigger asChild>
              <InputGroupButton
                aria-label={`What ${name} does`}
                size="icon-xs"
                type="button"
              >
                <FieldHelpIcon />
              </InputGroupButton>
            </TooltipTrigger>
            <TooltipContent className="max-w-64">{help}</TooltipContent>
          </Tooltip>
        </InputGroupAddon>
      </InputGroup>
    </Field>
  )
}

/** Shipped copy, word for word. */
function BandWarning({
  aboveCeiling,
  belowFloor,
}: {
  aboveCeiling: boolean
  belowFloor: boolean
}) {
  const reduce = useReducedMotion()
  const message = belowFloor
    ? `A maximum wait below ${formatSeconds(RECOMMENDED_MAX_WAIT_FLOOR_SECONDS)} increases the chance of interrupting callers mid-sentence.`
    : aboveCeiling
      ? `A maximum wait above ${formatSeconds(RECOMMENDED_MAX_WAIT_CEILING_SECONDS)} leaves callers waiting whenever the model is unsure, which is the delay this setting exists to reduce.`
      : null

  return (
    <AnimatePresence initial={false} mode="wait">
      {message ? (
        <motion.div
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -4 }}
          initial={{ opacity: 0, y: -4 }}
          key={belowFloor ? "below" : "above"}
          transition={
            reduce
              ? { duration: 0 }
              : { duration: 0.2, ease: [0.215, 0.61, 0.355, 1] }
          }
        >
          <Alert>
            <OutOfBandIcon className="text-warning" />
            <AlertDescription>{message}</AlertDescription>
          </Alert>
        </motion.div>
      ) : null}
    </AnimatePresence>
  )
}

"use client"

import { HugeiconsIcon, type IconSvgElement } from "@hugeicons/react"

/** No size of its own, so primitives size it through their `[&_svg]:size-4` rules. */
export function icon(glyph: IconSvgElement, displayName: string) {
  const Icon = (
    props: Omit<React.ComponentProps<typeof HugeiconsIcon>, "icon">,
  ) => <HugeiconsIcon icon={glyph} strokeWidth={1.8} {...props} />
  Icon.displayName = displayName
  return Icon
}

